import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.cT4_XGNl.js";const u=JSON.parse('{"title":"F2: Kinetic Navigation & Smooth Scrolling","description":"","frontmatter":{},"headers":[],"relativePath":"features/F2-kinetic-navigation-smoothscroll.md","filePath":"features/F2-kinetic-navigation-smoothscroll.md"}'),n={name:"features/F2-kinetic-navigation-smoothscroll.md"};function o(c,e,r,l,h,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="f2-kinetic-navigation-smooth-scrolling" tabindex="-1">F2: Kinetic Navigation &amp; Smooth Scrolling <a class="header-anchor" href="#f2-kinetic-navigation-smooth-scrolling" aria-label="Permalink to &quot;F2: Kinetic Navigation &amp; Smooth Scrolling&quot;">​</a></h1><h2 id="_1-description-user-experience" tabindex="-1">1. Description &amp; User Experience <a class="header-anchor" href="#_1-description-user-experience" aria-label="Permalink to &quot;1. Description &amp; User Experience&quot;">​</a></h2><p>The platform provides a unified kinetic feel across every page. Natural scroll wheel movements are intercepted by Lenis (<code>frontend/src/components/smoothscroll.jsx</code>) to produce smooth inertial acceleration and deceleration. Interactive buttons wrapped in <code>magnetic.jsx</code> pull toward the cursor when hovered, creating a tactile physical connection.</p><h2 id="_2-architecture-physics-calculations" tabindex="-1">2. Architecture &amp; Physics Calculations <a class="header-anchor" href="#_2-architecture-physics-calculations" aria-label="Permalink to &quot;2. Architecture &amp; Physics Calculations&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Wheel[Raw Scroll Event] --&gt; LenisEngine[Lenis Inertial Physics Buffer]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    LenisEngine --&gt; Interpolate[Virtual Scroll Delta Translation]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Interpolate --&gt; Viewport[Smooth Viewport Offset Update]</span></span></code></pre></div><h2 id="_3-say-it-out-loud" tabindex="-1">3. Say It Out Loud <a class="header-anchor" href="#_3-say-it-out-loud" aria-label="Permalink to &quot;3. Say It Out Loud&quot;">​</a></h2><p>&quot;I implemented a kinetic micro-interaction system combining Lenis smooth scrolling with magnetic physics buttons. When the user scrolls, Lenis intercepts the raw wheel event and applies a custom cubic easing equation to ensure fluid momentum across long technical articles. For interactive buttons, I built a custom magnetic component using GSAP springs that calculates the distance between the cursor and the element&#39;s center point, creating an attractive pull effect. I chose this over basic CSS hover states because it makes the web app feel alive and responsive. If a user enables &#39;prefers-reduced-motion&#39; in their system settings, the system automatically bypasses the physics calculations to respect accessibility standards.&quot;</p>`,7)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
